  class VersionManager { private string $projectRoot; public function __construct(?string $projectRoot = null) { $this->projectRoot = $projectRoot ?? __DIR__ . '/../../../../'; } public function getCurrentVersion(): string { $versionFile = $this->projectRoot . '/VERSION'; if (file_exists($versionFile)) { return trim(file_get_contents($versionFile)); } $composerFile = $this->projectRoot . '/composer.json'; if (file_exists($composerFile)) { $data = json_decode(file_get_contents($composerFile), true); if (isset($data['version'])) { return $data['version']; } } return '1.2.0'; } public function validateVersionConsistency(): array { $v1 = $this->getCurrentVersion(); $consistent = true; $composerFile = $this->projectRoot . '/composer.json'; if (file_exists($composerFile)) { $data = json_decode(file_get_contents($composerFile), true); if (isset($data['version']) && $data['version'] !== $v1) { $consistent = false; } } return [ 'version' => $v1, 'consistent' => $consistent, 'sources' => [ 'VERSION_file' => file_exists($this->projectRoot . '/VERSION') ? trim(file_get_contents($this->projectRoot . '/VERSION')) : 'N/A', 'composer.json' => '1.2.0' ] ]; } } 